mapper.select:
SELECT creator_id AS creatorId, creator_name AS creatorName, COUNT(*) AS videoCount, SUM(views) AS totalViews, SUM(likes) AS totalLikes, SUM(conversions) AS totalConversions, SUM(amount) AS totalAmount FROM video_data WHERE deleted = 0
AND publish_date >= #{startDate}
AND publish_date <= #{endDate}
GROUP BY creator_id, creator_name ORDER BY totalViews DESC

SELECT DATE_FORMAT(publish_date, '%Y-%m-%d') AS statDate, COUNT(*) AS videoCount, SUM(views) AS totalViews, SUM(likes) AS totalLikes, SUM(conversions) AS totalConversions FROM video_data WHERE deleted = 0
AND publish_date >= #{startDate}
AND publish_date <= #{endDate}
GROUP BY DATE_FORMAT(publish_date, '%Y-%m-%d') ORDER BY statDate

SELECT t.id AS topicId, t.title AS topicTitle, COUNT(v.id) AS videoCount, SUM(v.views) AS totalViews, SUM(v.likes) AS totalLikes, SUM(v.conversions) AS totalConversions, SUM(v.amount) AS totalAmount, AVG(v.conversion_rate) AS avgConversionRate FROM topic t LEFT JOIN video_data v ON t.id = v.topic_id AND v.deleted = 0 WHERE t.deleted = 0
AND v.publish_date >= #{startDate}
AND v.publish_date <= #{endDate}
GROUP BY t.id, t.title HAVING videoCount > 0 ORDER BY totalViews DESC
